import React, { useState } from "react";
import {
  Box,
  Button,
  Flex,
  Heading,
  Image,
  Input,
  Radio,
  RadioGroup,
  Stack,
  Text,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  useDisclosure,
  Divider,
  useToast,
} from "@chakra-ui/react";
import { useSelector, useDispatch } from "react-redux";
import MenuNavbar from "../../components/navbar/menuNavbar/MenuNavbar";
import rupee from "../../assets/rupee.png";
import "./Cart.scss";

const Cart = () => {
  const [paymentMethod, setPaymentMethod] = useState("creditCard");
  const [billingDetails, setBillingDetails] = useState({
    name: "",
    email: "",
    address: "",
    city: "",
    zipCode: "",
    country: "",
  });
  const { isOpen, onOpen, onClose } = useDisclosure();
  const toast = useToast();
  const dispatch = useDispatch();
  const cartItems = useSelector((state) => state.cart.cartItems);

  const deliveryCharge = 40;
  const estimatedTime = 30;

  const calculateSubtotal = () => {
    return cartItems.reduce((acc, item) => {
      const price = item.price ? item.price / 100 : item.defaultPrice / 100;
      return acc + price * item.quantity;
    }, 0).toFixed(2);
  };

  const calculateTotal = () => {
    return (parseFloat(calculateSubtotal()) + deliveryCharge).toFixed(2);
  };

  const handleCheckout = () => {
    if (Object.values(billingDetails).some((value) => !value)) {
      toast({
        title: "Billing Details Incomplete",
        description: "Please fill out all billing details before proceeding.",
        status: "error",
        duration: 3000,
        isClosable: true,
      });
    } else {
      onOpen();
    }
  };

  return (
    <>
      <MenuNavbar cart="cart" />
      <Box p={6} m="auto" bg="gray.50" borderRadius="md" boxShadow="md" className="cart-container">
        <Heading as="h2" size="xl" mb={6} textAlign="center">Your Cart</Heading>
        <Stack spacing={4}>
          {cartItems.map((item) => (
            <Flex key={item.id} justify="space-between" align="center" p={4} bg="white" borderRadius="md" boxShadow="sm">
              <Text fontWeight="bold">{item.name}</Text>
              <Flex align="center">
                <Button size="sm" onClick={() => dispatch(decrementQuantity(item.id))} isDisabled={item.quantity <= 1}>-</Button>
                <Text mx={2}>{item.quantity}</Text>
                <Button size="sm" onClick={() => dispatch(incrementQuantity(item.id))}>+</Button>
              </Flex>
              <Text fontWeight="bold" display="flex" alignItems="center" gap="3px">
                <Image src={rupee} alt="rupee" boxSize={3} />
                {(item.price / 100 * item.quantity).toFixed(2)}
              </Text>
            </Flex>
          ))}
        </Stack>
        <Divider my={6} />
        <Flex justify="space-between" align="center" mb={4}>
          <Text fontSize="lg">Subtotal:</Text>
          <Text fontSize="lg" fontWeight="bold" display="flex" alignItems="center" gap="3px">
            <Image src={rupee} alt="rupee" boxSize={3} /> {calculateSubtotal()}
          </Text>
        </Flex>
        <Flex justify="space-between" align="center" mb={4}>
          <Text fontSize="xl">Total:</Text>
          <Text fontSize="xl" fontWeight="bold" display="flex" alignItems="center" gap="3px">
            <Image src={rupee} alt="rupee" boxSize={3} /> {calculateTotal()}
          </Text>
        </Flex>
        <Button colorScheme="teal" size="lg" width="100%" onClick={handleCheckout}>Pay</Button>
      </Box>
    </>
  );
};

export default Cart;
